{"content": "1|import { VERTEX_SHADER, FRAGMENT_SHADER } from './shaders.js';
2|import { FLOATS_PER_VERTEX } from './meshBuilder.js';
3|import { identity } from '../core/math.js';
4|
5|const UNIFORMS = ['uProj', 'uView', 'uModel', 'uEye', 'uSunDir', 'uFogColor', 'uFogDensity', 'uTime'];
6|
7|/** Thin WebGL2 wrapper: one program, static meshes, one draw call per mesh. */
8|export class Renderer {
9|  constructor(canvas) {
10|    const gl = canvas.getContext('webgl2', { antialias: true });
11|    if (!gl) throw new Error('WebGL2 is not available in this browser.');
12|    this.gl = gl;
13|    this.canvas = canvas;
14|    this.program = createProgram(gl, VERTEX_SHADER, FRAGMENT_SHADER);
15|    this.u = Object.fromEntries(UNIFORMS.map((name) => [name, gl.getUniformLocation(this.program, name)]));
16|    gl.enable(gl.DEPTH_TEST);
17|    gl.enable(gl.CULL_FACE);
18|    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
19|  }
20|
21|  /** Uploads a MeshBuilder to the GPU. Returns a handle for draw(). */
22|  upload(builder) {
23|    const gl = this.gl;
24|    const vao = gl.createVertexArray();
25|    gl.bindVertexArray(vao);
26|    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
27|    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(builder.vertices), gl.STATIC_DRAW);
28|    const stride = FLOATS_PER_VERTEX * 4;
29|    [3, 3, 3, 1].reduce((offset, size, loc) => {
30|      gl.enableVertexAttribArray(loc);
31|      gl.vertexAttribPointer(loc, size, gl.FLOAT, false, stride, offset * 4);
32|      return offset + size;
33|    }, 0);
34|    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, gl.createBuffer());
35|    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint32Array(builder.indices), gl.STATIC_DRAW);
36|    gl.bindVertexArray(null);
37|    return { vao, count: builder.indices.length };
38|  }
39|
40|  /** Matches the drawing buffer to the CSS size. Returns the aspect ratio. */
41|  resize() {
42|    const dpr = Math.min(window.devicePixelRatio || 1, 2);
43|    const w = Math.round(this.canvas.clientWidth * dpr), h = Math.round(this.canvas.clientHeight * dpr);
44|    if (this.canvas.width !== w || this.canvas.height !== h) {
45|      this.canvas.width = w;
46|      this.canvas.height = h;
47|    }
48|    this.gl.viewport(0, 0, w, h);
49|    return w / Math.max(h, 1);
50|  }
51|
52|  /** view = { proj, view, eye }, env = { sunDir, fogColor, fogDensity, time } */
53|  beginFrame(view, env) {
54|    const gl = this.gl, u = this.u;
55|    gl.clearColor(...env.fogColor, 1);
56|    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
57|    gl.useProgram(this.program);
58|    gl.uniformMatrix4fv(u.uProj, false, view.proj);
59|    gl.uniformMatrix4fv(u.uView, false, view.view);
60|    gl.uniform3fv(u.uEye, view.eye);
61|    gl.uniform3fv(u.uSunDir, env.sunDir);
62|    gl.uniform3fv(u.uFogColor, env.fogColor);
63|    gl.uniform1f(u.uFogDensity, env.fogDensity);
64|    gl.uniform1f(u.uTime, env.time);
65|  }
66|
67|  draw(mesh, model = identity(), transparent = false) {
68|    const gl = this.gl;
69|    if (transparent) {
70|      gl.enable(gl.BLEND);
71|      gl.depthMask(false);
72|    }
73|    gl.uniformMatrix4fv(this.u.uModel, false, model);
74|    gl.bindVertexArray(mesh.vao);
75|    gl.drawElements(gl.TRIANGLES, mesh.count, gl.UNSIGNED_INT, 0);
76|    if (transparent) {
77|      gl.disable(gl.BLEND);
78|      gl.depthMask(true);
79|    }
80|  }
81|}
82|
83|function createProgram(gl, vsSource, fsSource) {
84|  const compile = (type, src) => {
85|    const s = gl.createShader(type);
86|    gl.shaderSource(s, src);
87|    gl.compileShader(s);
88|    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s));
89|    return s;
90|  };
91|  const p = gl.createProgram();
92|  gl.attachShader(p, compile(gl.VERTEX_SHADER, vsSource));
93|  gl.attachShader(p, compile(gl.FRAGMENT_SHADER, fsSource));
94|  gl.linkProgram(p);
95|  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(p));
96|  return p;
97|}", "total_lines": 97, "file_size": 3716, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Builds triangle meshes on the CPU from primitive shapes.
3| *
4| * Every vertex carries: position(3) normal(3) color(3) material(1).
5| * The material id tells the fragment shader which procedural pattern to paint
6| * (windows, water, asphalt ...), so no textures are needed.
7| *
8| * Shapes are flat-shaded (one normal per face) for a clean low-poly look.
9| * Faces are oriented automatically: pass a point that lies inside the solid
10| * and the face will point away from it (correct normal + CCW winding).
11| */
12|
13|export const FLOATS_PER_VERTEX = 10;
14|
15|export const MAT = {
16|  PLAIN: 0,
17|  ALTBAU: 1, // pre-war facade: tall windows, shop fronts on the ground floor
18|  PLATTE: 2, // prefab panel building: panel joints, dense window grid
19|  WATER: 3,
20|  ASPHALT: 4,
21|  PAINT: 5, // glossy (car paint, glass, metal)
22|  SHADOW: 6, // soft blob shadow, color.xy carries the uv
23|};
24|
25|/** 0xRRGGBB -> [r, g, b] in 0..1 */
26|export const rgb = (hex) => [((hex >> 16) & 255) / 255, ((hex >> 8) & 255) / 255, (hex & 255) / 255];
27|
28|export class MeshBuilder {
29|  constructor() {
30|    this.vertices = [];
31|    this.indices = [];
32|  }
33|
34|  get vertexCount() {
35|    return this.vertices.length / FLOATS_PER_VERTEX;
36|  }
37|
38|  /** Convex planar polygon. `inside` is a point the normal should point away from. */
39|  poly(pts, color, mat = MAT.PLAIN, inside = null) {
40|    // Newell's method: robust normal for any planar polygon.
41|    let nx = 0, ny = 0, nz = 0, cx = 0, cy = 0, cz = 0;
42|    for (let i = 0; i < pts.length; i++) {
43|      const a = pts[i], b = pts[(i + 1) % pts.length];
44|      nx += (a[1] - b[1]) * (a[2] + b[2]);
45|      ny += (a[2] - b[2]) * (a[0] + b[0]);
46|      nz += (a[0] - b[0]) * (a[1] + b[1]);
47|      cx += a[0]; cy += a[1]; cz += a[2];
48|    }
49|    const len = Math.hypot(nx, ny, nz);
50|    if (len < 1e-9) return; // degenerate
51|    nx /= len; ny /= len; nz /= len;
52|    if (inside) {
53|      const n = pts.length;
54|      const dot = nx * (cx / n - inside[0]) + ny * (cy / n - inside[1]) + nz * (cz / n - inside[2]);
55|      if (dot < 0) {
56|        pts = pts.slice().reverse();
57|        nx = -nx; ny = -ny; nz = -nz;
58|      }
59|    }
60|    const base = this.vertexCount;
61|    for (const p of pts) this.vertices.push(p[0], p[1], p[2], nx, ny, nz, color[0], color[1], color[2], mat);
62|    for (let i = 1; i < pts.length - 1; i++) this.indices.push(base, base + i, base + i + 1);
63|  }
64|
65|  /** Horizontal rectangle facing up. */
66|  rect(x0, z0, x1, z1, y, color, mat = MAT.PLAIN) {
67|    this.poly([[x0, y, z0], [x1, y, z0], [x1, y, z1], [x0, y, z1]], color, mat, [x0, y - 1, z0]);
68|  }
69|
70|  /** Axis-aligned box. opts: { mat, top (color), topMat, bottom (bool) } */
71|  box(x0, y0, z0, x1, y1, z1, color, opts = {}) {
72|    const mat = opts.mat ?? MAT.PLAIN;
73|    const c = [(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2];
74|    this.poly([[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0]], color, mat, c);
75|    this.poly([[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]], color, mat, c);
76|    this.poly([[x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0]], color, mat, c);
77|    this.poly([[x1, y0, z0], [x1, y0, z1], [x1, y1, z1], [x1, y1, z0]], color, mat, c);
78|    this.poly([[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]], opts.top ?? color, opts.topMat ?? mat, c);
79|    if (opts.bottom) this.poly([[x0, y0, z0], [x1, y0, z0], [x1, y0, z1], [x0, y0, z1]], color, mat, c);
80|  }
81|
82|  /** Vertical cone stump around (cx, cz). r1 === r0 gives a cylinder, r1 === 0 a cone. */
83|  frustum(cx, y0, cz, r0, y1, r1, segs, color, mat = MAT.PLAIN) {
84|    const inside = [cx, (y0 + y1) / 2, cz];
85|    const ring = (r, y) => Array.from({ length: segs }, (_, i) => {
86|      const a = (i / segs) * Math.PI * 2;
87|      return [cx + Math.cos(a) * r, y, cz + Math.sin(a) * r];
88|    });
89|    const lo = ring(r0, y0), hi = ring(r1, y1);
90|    for (let i = 0; i < segs; i++) {
91|      const j = (i + 1) % segs;
92|      this.poly(r1 > 0 ? [lo[i], lo[j], hi[j], hi[i]] : [lo[i], lo[j], [cx, y1, cz]], color, mat, inside);
93|    }
94|    if (r1 > 0) this.poly(hi, color, mat, inside);
95|  }
96|
97|  /** Cylinder lying along the X axis (wheels). */
98|  cylinderX(x0, x1, cy, cz, r, segs, color, mat = MAT.PLAIN) {
99|    const inside = [(x0 + x1) / 2, cy, cz];
100|    const ring = (x) => Array.from({ length: segs }, (_, i) => {
101|      const a = (i / segs) * Math.PI * 2;
102|      return [x, cy + Math.cos(a) * r, cz + Math.sin(a) * r];
103|    });
104|    const a = ring(x0), b = ring(x1);
105|    for (let i = 0; i < segs; i++) {
106|      const j = (i + 1) % segs;
107|      this.poly([a[i], a[j], b[j], b[i]], color, mat, inside);
108|    }
109|    this.poly(a, color, mat, inside);
110|    this.poly(b, color, mat, inside);
111|  }
112|
113|  /** Low-poly (ellipsoid) sphere. stretchY scales the vertical radius. */
114|  sphere(cx, cy, cz, r, segs, rings, color, mat = MAT.PLAIN, stretchY = 1) {
115|    const p = (t, a) => [
116|      cx + r * Math.sin(t) * Math.cos(a),
117|      cy + r * stretchY * Math.cos(t),
118|      cz + r * Math.sin(t) * Math.sin(a),
119|    ];
120|    for (let j = 0; j < rings; j++) {
121|      const t0 = (Math.PI * j) / rings, t1 = (Math.PI * (j + 1)) / rings;
122|      for (let i = 0; i < segs; i++) {
123|        const a0 = (i / segs) * Math.PI * 2, a1 = ((i + 1) / segs) * Math.PI * 2;
124|        const pts = j === 0 ? [p(t0, a0), p(t1, a1), p(t1, a0)]
125|          : j === rings - 1 ? [p(t0, a0), p(t0, a1), p(t1, a0)]
126|          : [p(t0, a0), p(t0, a1), p(t1, a1), p(t1, a0)];
127|        this.poly(pts, color, mat, [cx, cy, cz]);
128|      }
129|    }
130|  }
131|}", "total_lines": 131, "file_size": 5390, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Procedural German taxi: light-ivory saloon with the yellow "TAXI" roof sign.
3| * Local space: +Z forward, +X left, Y up, origin on the ground between the axles.
4| */
5|import { MeshBuilder, MAT, rgb } from '../gfx/meshBuilder.js';
6|
7|const IVORY = rgb(0xe8dcb0); // RAL 1015 "Hellelfenbein", the classic German taxi colour
8|const GLASS = rgb(0x1d252d), TRIM = rgb(0x2a2a2a), SIGN = rgb(0xf5c400), INK = rgb(0x111111);
9|const HEADLIGHT = rgb(0xfff4d6), TAILLIGHT = rgb(0xb3121b), TIRE = rgb(0x1b1b1b), RIM = rgb(0xb9bcc0);
10|
11|// 3x5 pixel font, rows top to bottom. All four letters are mirror-symmetric,
12|// so the sign reads correctly from the front and from behind.
13|const FONT = { T: '111010010010010', A: '010101111101101', X: '101101010101101', I: '111010010010111' };
14|
15|/** Returns three MeshBuilders: body, one wheel (centred on its axle) and the blob shadow. */
16|export function buildTaxi(spec) {
17|  return { body: buildBody(), wheel: buildWheel(spec), shadow: buildShadow() };
18|}
19|
20|/** Wheel hub positions in local space. Front wheels steer. */
21|export function wheelOffsets(spec) {
22|  const x = spec.trackWidth / 2, z = spec.wheelBase / 2, y = spec.wheelRadius;
23|  return [
24|    { x, y, z, front: true }, { x: -x, y, z, front: true },
25|    { x, y, z: -z, front: false }, { x: -x, y, z: -z, front: false },
26|  ];
27|}
28|
29|function buildBody() {
30|  const m = new MeshBuilder();
31|  const paint = { mat: MAT.PAINT };
32|  m.box(-0.92, 0.28, -2.45, 0.92, 0.82, 2.45, IVORY, paint); // lower body
33|  m.box(-0.8, 0.82, -1.45, 0.8, 1.42, 0.9, IVORY, paint); // cabin
34|  m.box(-0.7, 0.9, 0.9, 0.7, 1.36, 0.93, GLASS, paint); // windscreen
35|  m.box(-0.7, 0.9, -1.48, 0.7, 1.36, -1.45, GLASS, paint); // rear window
36|  for (const x of [-0.83, 0.8]) {
37|    m.box(x, 0.92, -1.3, x + 0.03, 1.36, 0.8, GLASS, paint); // side windows
38|    m.box(x - 0.01, 0.92, -0.32, x + 0.04, 1.38, -0.2, IVORY, paint); // B-pillar
39|  }
40|  for (const s of [-1, 1]) m.box(s > 0 ? 0.92 : -1.02, 1.0, 0.68, s > 0 ? 1.02 : -0.92, 1.1, 0.82, IVORY, paint); // mirrors
41|  m.box(-0.94, 0.25, 2.4, 0.94, 0.45, 2.55, TRIM); // bumpers
42|  m.box(-0.94, 0.25, -2.55, 0.94, 0.45, -2.4, TRIM);
43|  m.box(-0.4, 0.5, 2.45, 0.4, 0.74, 2.47, TRIM); // grille
44|  for (const [a, b] of [[-0.86, -0.5], [0.5, 0.86]]) {
45|    m.box(a, 0.6, 2.45, b, 0.74, 2.48, HEADLIGHT, paint);
46|    m.box(a, 0.6, -2.48, b, 0.74, -2.45, TAILLIGHT, paint);
47|  }
48|
49|  // Roof sign with "TAXI" built from tiny boxes on both faces.
50|  m.box(-0.3, 1.42, -0.5, 0.3, 1.64, -0.25, SIGN, paint);
51|  const px = 0.032, word = 'TAXI', width = (word.length * 4 - 1) * px;
52|  [...word].forEach((ch, li) => {
53|    for (let i = 0; i < 15; i++) {
54|      if (FONT[ch][i] !== '1') continue;
55|      const x = -width / 2 + (li * 4 + (i % 3)) * px, y = 1.6 - (Math.floor(i / 3) + 1) * px;
56|      m.box(x, y, -0.25, x + px, y + px, -0.24, INK); // front face, reads along +X
57|      m.box(-x - px, y, -0.51, -x, y + px, -0.5, INK); // back face, mirrored
58|    }
59|  });
60|  return m;
61|}
62|
63|function buildWheel(spec) {
64|  const m = new MeshBuilder(), r = spec.wheelRadius;
65|  m.cylinderX(-0.11, 0.11, 0, 0, r, 14, TIRE);
66|  m.cylinderX(-0.115, 0.115, 0, 0, r * 0.6, 10, RIM, MAT.PAINT);
67|  m.box(-0.12, -0.03, 0.05, 0.12, 0.03, 0.17, TRIM); // hub marker, makes the spin visible
68|  return m;
69|}
70|
71|/** Soft shadow: one quad whose vertex colors carry uv coordinates for the shader. */
72|function buildShadow() {
73|  const m = new MeshBuilder();
74|  for (const [u, v] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) {
75|    m.vertices.push(u * 1.15, 0.03, v * 2.7, 0, 1, 0, u, v, 0, MAT.SHADOW);
76|  }
77|  m.indices.push(0, 2, 1, 0, 3, 2);
78|  return m;
79|}", "total_lines": 79, "file_size": 3578, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|import { lookAt, perspective, damp, lerp } from '../core/math.js';
2|
3|/** Camera rigs relative to the car. Each returns [eye, target, smoothingRate]. */
4|const RIGS = {
5|  chase: (x, z, fx, fz) => [[x - fx * 7.5, 3.2, z - fz * 7.5], [x + fx * 3, 1.1, z + fz * 3], 7],
6|  hood: (x, z, fx, fz) => [[x + fx * 1.1, 1.15, z + fz * 1.1], [x + fx * 10, 1.0, z + fz * 10], Infinity],
7|  top: (x, z, fx, fz) => [[x - fx * 20, 70, z - fz * 20], [x, 0, z], 4],
8|};
9|const MODES = Object.keys(RIGS);
10|
11|export class Camera {
12|  constructor() {
13|    this.mode = 0;
14|    this.eye = [0, 0, 0];
15|    this.target = [0, 0, 0];
16|    this.snapNext = true;
17|  }
18|
19|  get modeName() {
20|    return MODES[this.mode];
21|  }
22|
23|  next() {
24|    this.mode = (this.mode + 1) % MODES.length;
25|    this.snapNext = true;
26|  }
27|
28|  /** Skip smoothing on the next update (after a reset or mode change). */
29|  snap() {
30|    this.snapNext = true;
31|  }
32|
33|  update(car, dt) {
34|    const [eye, target, rate] = RIGS[this.modeName](car.x, car.z, Math.sin(car.heading), Math.cos(car.heading));
35|    const t = this.snapNext ? 1 : damp(rate, dt);
36|    this.snapNext = false;
37|    for (let i = 0; i < 3; i++) {
38|      this.eye[i] = lerp(this.eye[i], eye[i], t);
39|      this.target[i] = lerp(this.target[i], target[i], t);
40|    }
41|  }
42|
43|  matrices(aspect) {
44|    const fov = this.modeName === 'hood' ? 1.2 : 1.0;
45|    return { proj: perspective(fov, aspect, 0.5, 1500), view: lookAt(this.eye, this.target), eye: this.eye };
46|  }
