{"content": "1|// The multiplayer message language: one entry per message type, declaring its
2|// direction ('cs' client → server, 'sc' server → client), its wire fields and
3|// its design rate. One shared encode/decode pair is driven by those entries,
4|// so every packet is validated against the same definitions that produce the
5|// protocol table in NOTES.md (`node tools/protocol-table.mjs`).
6|//
7|// Wire format: JSON text frames tagged with `type` — messages are tiny and the
8|// intranet is fast, so readable beats compact. All times are milliseconds in
9|// the shared server clock (clients learn their offset via ping/pong, because
10|// the browser's WebSocket API hides the protocol-level ping/pong from JS).
11|
12|export const STAGES = ['lobby', 'countdown', 'racing', 'finished', 'ceremony'];
13|export const MAX_PLAYERS = 4;
14|
15|const err = (where, why) => new Error(`protocol: ${where} ${why}`);
16|
17|// --- Field validators (used by encode AND decode, so both sides agree) ---
18|
19|function str(v, w) {
20|  if (typeof v !== 'string' || v.length < 1 || v.length > 24) throw err(w, 'must be a 1..24 char string');
21|  return v;
22|}
23|function num(v, w) {
24|  if (typeof v !== 'number' || !Number.isFinite(v)) throw err(w, 'must be a finite number');
25|  return v;
26|}
27|function idNum(v, w) {
28|  if (!Number.isInteger(v) || v < 1) throw err(w, 'must be a positive integer');
29|  return v;
30|}
31|function seedNum(v, w) {
32|  if (!Number.isInteger(v) || v < 0) throw err(w, 'must be a non-negative integer');
33|  return v;
34|}
35|function stageOf(v, w) {
36|  if (!STAGES.includes(v)) throw err(w, `must be one of ${STAGES.join('|')}`);
37|  return v;
38|}
39|function rosterOf(v, w) {
40|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
41|  return v.map((p, i) => {
42|    if (typeof p !== 'object' || p === null || Array.isArray(p)) throw err(`${w}[${i}]`, 'must be an object');
43|    for (const k of Object.keys(p)) if (k !== 'id' && k !== 'name') throw err(`${w}[${i}]`, `has unknown field ${k}`);
44|    if (!('id' in p) || !('name' in p)) throw err(`${w}[${i}]`, 'needs id and name');
45|    return { id: idNum(p.id, `${w}[${i}].id`), name: str(p.name, `${w}[${i}].name`) };
46|  });
47|}
48|
49|const tOrNull = (v, w) => (v === null ? null : num(v, w));
50|// A jump-start penalty: milliseconds the server added to a finisher's time, or
51|// null on a DNF row (no crossing time, nothing to penalise).
52|const penOf = (v, w) => {
53|  if (v === null) return null;
54|  if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) throw err(w, 'must be a non-negative number or null');
55|  return v;
56|};
57|const boolOf = (v, w) => {
58|  if (typeof v !== 'boolean') throw err(w, 'must be a boolean');
59|  return v;
60|};
61|// One results-table row for the settled race: finished players first in
62|// official order (time + penalty, then earliest report), DNFs last with
63|// t = null and pen = null.
64|const resultsOf = (v, w) => {
65|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
66|  return v.map((r, i) => {
67|    if (typeof r !== 'object' || r === null || Array.isArray(r)) throw err(`${w}[${i}]`, 'must be an object');
68|    for (const k of Object.keys(r)) if (k !== 'id' && k !== 'name' && k !== 't' && k !== 'dnf' && k !== 'pen') throw err(`${w}[${i}]`, `has unknown field ${k}`);
69|    if (!('id' in r) || !('name' in r) || !('t' in r) || !('dnf' in r) || !('pen' in r)) throw err(`${w}[${i}]`, 'needs id, name, t, dnf and pen');
70|    return {
71|      id: idNum(r.id, `${w}[${i}].id`),
72|      name: str(r.name, `${w}[${i}].name`),
73|      t: tOrNull(r.t, `${w}[${i}].t`),
74|      dnf: boolOf(r.dnf, `${w}[${i}].dnf`),
75|      pen: penOf(r.pen, `${w}[${i}].pen`),
76|    };
77|  });
78|};
79|
80|// --- The registry ---
81|
82|export const MESSAGES = {
83|  // client → server
84|  join:       { dir: 'cs', rate: 'once, on entering the lobby', fields: { name: str } },
85|  name:       { dir: 'cs', rate: 'on change, in lobby',          fields: { name: str } },
86|  start:      { dir: 'cs', rate: 'user-triggered',               fields: {} },
87|  pos:        { dir: 'cs', rate: '15 Hz while racing',           fields: { x: num, z: num, h: num, s: num } },
88|  finish:     { dir: 'cs', rate: 'once per race',                fields: { t: num } },
89|  jump:       { dir: 'cs', rate: 'user-triggered, before green', fields: {} },
90|  again:      { dir: 'cs', rate: 'user-triggered, in ceremony',  fields: {} },
91|  ping:       { dir: 'cs', rate: 'about 1 Hz while syncing',     fields: { t: num } },
92|  // server → client
93|  roster:     { dir: 'sc', rate: 'on change',                    fields: { players: rosterOf, seed: seedNum } },
94|  countdown:  { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
95|  go:         { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
96|  posRelay:   { dir: 'sc', rate: 'per player, 15 Hz',            fields: { id: idNum, x: num, z: num, h: num, s: num } },
97|  stage:      { dir: 'sc', rate: 'on change',                    fields: { stage: stageOf } },
98|  disconnect: { dir: 'sc', rate: 'on player leaving',            fields: { id: idNum } },
99|  pong:       { dir: 'sc', rate: 'on ping',                      fields: { t: num, s: num } },
100|  finishInfo: { dir: 'sc', rate: 'per finisher, once',           fields: { id: idNum, t: num } },
101|  jumped:     { dir: 'sc', rate: 'per jump, once',              fields: { id: idNum, pen: num } },
102|  results:    { dir: 'sc', rate: 'once, when the race is settled', fields: { players: resultsOf } },
103|};
104|
105|// --- The encode/decode pair ---
106|
107|// encode(type, data) → JSON string, fields validated on the way out.
108|export function encode(type, data) {
109|  const def = MESSAGES[type];
110|  if (!def) throw err(type, 'is not a known message type');
111|  const out = { type };
112|  for (const [f, check] of Object.entries(def.fields)) out[f] = check(data?.[f], `${type}.${f}`);
113|  return JSON.stringify(out);
114|}
115|
116|// decode(text) → { type, data }, or throws on anything unknown or malformed:
117|// bad JSON, non-objects, unknown types, missing/unknown fields, wrong value types.
118|export function decode(text) {
119|  let m = null;
120|  try { m = JSON.parse(text); } catch { /* handled below */ }
121|  if (typeof m !== 'object' || m === null || Array.isArray(m)) throw err('packet', 'must be a JSON object');
122|  const def = MESSAGES[m.type];
123|  if (!def) throw err('packet', `unknown message type ${JSON.stringify(m.type)}`);
124|  const known = Object.keys(def.fields);
125|  for (const k of Object.keys(m)) if (k !== 'type' && !known.includes(k)) throw err(m.type, `unknown field ${k}`);
126|  const data = {};
127|  for (const [f, check] of Object.entries(def.fields)) data[f] = check(m[f], `${m.type}.${f}`);
128|  return { type: m.type, data };
129|}
130|
131|// Markdown table of the whole protocol, generated from the registry. NOTES.md
132|// embeds it between markers; a test keeps the two from drifting apart.
133|export function protocolTable() {
134|  const rows = Object.entries(MESSAGES).map(([name, d]) =>
135|    `| ${name} | ${d.dir === 'cs' ? 'client → server' : 'server → client'} | ${Object.keys(d.fields).join(' ') || '—'} | ${d.rate} |`);
136|  return ['| type | from | fields | rate |', '|---|---|---|---|', ...rows].join('\n');
137|}", "total_lines": 137, "file_size": 7143, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Master-clock maths for the online race. PURE: no DOM, no timers — a client
3| * feeds it pong replies, it keeps the best estimate of the server clock.
4| *
5| * Why the app-level ping/pong instead of WebSocket pings? The browser API
6| * hides protocol-level pings from JavaScript, so the client sends `ping`
7| * {t: local send time}; the server replies `pong` {t: echoed, s: server clock}.
8| * With a roughly symmetric wire, the server's "now" sits in the middle of the
9| * round trip, giving the offset from the client clock to the server clock:
10| *
11| *   rtt    = receiveTime − sentT
12| *   offset = serverS + rtt / 2 − receiveTime   (serverNow = localNow + offset)
13| *
14| * Network jitter inflates individual rtts, so the estimate always comes from
15| * the sample with the SMALLEST rtt of the last N pongs: the fast samples
16| * waited least in queues, so distorted least. Clients keep re-syncing (the
17| * lobby pings at ~1 Hz) before the shared start moment counts down, and the
18| * same serverNow() decides when ONE shared goAt has arrived — so every
19| * client, whatever its wire, flips the ampel to green at the same server
20| * instant.
21| * Counts toward the size budget — kept tight.
22| */
23|
24|/** One clock. history = pong samples kept for the min-rtt filter. */
25|export function createClock(history = 8) {
26|  const samples = []; // {rtt, offset}, newest last
27|  return {
28|    /** Feed one pong: echoedT = our send timestamp echoed back, serverAt = server clock reading, receiveTime = local receive time. */
29|    onPong(echoedT, serverAt, receiveTime) {
30|      const rtt = Math.max(0, receiveTime - echoedT);
31|      samples.push({ rtt, offset: serverAt + rtt / 2 - receiveTime });
32|      while (samples.length > history) samples.shift();
33|    },
34|    /** Best offset estimate, or null before the first pong. */
35|    offset() {
36|      let best = null;
37|      for (const s of samples) if (!best || s.rtt < best.rtt) best = s;
38|      return best ? best.offset : null;
39|    },
40|    /** True once at least one pong has been measured. */
41|    synced() { return samples.length > 0; },
42|    /** Convert a local time to the master clock. Returns null while unsynced. */
43|    serverNow(localNow) {
44|      const offset = this.offset();
45|      return offset === null ? null : localNow + offset;
46|    },
47|  };
48|}", "total_lines": 48, "file_size": 2272, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Remote-car interpolation buffer: push({t, x, z, h, s}) peer snapshots in
3| * local receive time, sample(renderNow, delayMs) reads ~100 ms behind the
4| * render clock, so uneven arrival times (jitter) never show on screen.
5| * PURE and deterministic — no timers, no randomness, no DOM.
6| *
7| * Never teleports backwards: a snapshot whose t is not newer than the stored
8| * newest is ignored. Past the newest snapshot the car simply holds (clamp);
9| * the peer's next update catches it back up. Heading glides along the SHORTEST
10| * arc between snapshots (track convention: 0 = facing +z, east = +π/2).
11| * Counts toward the size budget — kept tight.
12| */
13|
14|const TAU = Math.PI * 2;
15|
16|// Angle aliases into the −π..π branch.
17|const norm = (h) => { const a = (h % TAU + TAU) % TAU; return a > Math.PI ? a - TAU : a; };
18|
19|// Snapshot state minus the bookkeeping field t: exactly what a renderer wants.
20|const pick = (q) => ({ x: q.x, z: q.z, h: q.h, s: q.s });
21|
22|/** One interpolation buffer for one remote car. */
23|export function createInterp() {
24|  const buf = []; // {t, x, z, h, s}, oldest first, newest last
25|  return {
26|    /** Store one peer snapshot in receive order; older/equal t is ignored. */
27|    push(st) {
28|      if (buf.length && st.t <= buf[buf.length - 1].t) return;
29|      buf.push({ t: st.t, x: st.x, z: st.z, h: st.h, s: st.s });
30|      if (buf.length > 64) buf.shift(); // ~4 s at 15 Hz is plenty of history
31|    },
32|    /**
33|     * Interpolated car state at renderNow − delayMs (linear position/speed,
34|     * shortest-arc heading), or null before any snapshot. Before the first /
35|     * past the newest snapshot the earliest/newest state is returned as-is.
36|     */
37|    sample(renderNow, delayMs = 100) {
38|      if (!buf.length) return null;
39|      const rT = renderNow - delayMs;
40|      if (rT <= buf[0].t) return pick(buf[0]); // play has not begun: hold the car where it first appeared
41|      let i = buf.length - 1;
42|      if (rT >= buf[i].t) return pick(buf[i]); // clamp: no extrapolation past the newest
43|      for (i = 0; buf[i + 1].t <= rT; i++); // slide to the segment [i, i+1] surrounding rT
44|      const a = buf[i], b = buf[i + 1];
45|      const f = (rT - a.t) / (b.t - a.t);
46|      return {
47|        x: a.x + (b.x - a.x) * f,
48|        z: a.z + (b.z - a.z) * f,
49|        h: norm(a.h + norm(b.h - a.h) * f), // shortest arc, back into −π..π
50|        s: a.s + (b.s - a.s) * f,
51|      };
52|    },
53|  };
54|}", "total_lines": 54, "file_size": 2411, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Arcade car physics using a kinematic bicycle model.
3| * PURE: no DOM, no WebGL — runs in Node for tests.
4| *
5| * Car state: position (x, z), heading (rad, 0 = facing +Z / south), speed (m/s,
6| * negative when reversing), steer (front wheel angle in rad, + = left).
7| */
8|import { approach } from '../core/math.js';
9|
10|/** Tuning for a typical German taxi (mid-size saloon). */
11|export const TAXI = {
12|  wheelBase: 2.9, // m between axles
13|  trackWidth: 1.64, // m between left and right wheels
14|  wheelRadius: 0.34,
15|  maxSteer: 0.6, // rad at standstill
16|  steerRate: 2.5, // rad/s the steering wheel can turn
17|  maxLateralAccel: 14, // m/s² — arcade grip (a real saloon manages ~9)
18|  engineAccel: 6.5, // m/s² at standstill, fades out towards maxSpeed
19|  brakeDecel: 14,
20|  reverseAccel: 4,
21|  maxSpeed: 36, // m/s ≈ 130 km/h
22|  maxReverse: 8,
23|  rollingResistance: 0.4, // m/s²
24|  airDrag: 0.0022, // m/s² per (m/s)²
25|  handbrakeDecel: 9,
26|  collisionRadius: 0.95, // the body is approximated by two circles
27|  collisionOffset: 1.45, // their distance from the centre along the car axis
28|  restitution: 0.25, // bounce on impact
29|};
30|
31|export function createCar({ x, z, heading }) {
32|  return { x, z, heading, speed: 0, steer: 0, wheelSpin: 0 };
33|}
34|
35|/**
36| * Advances the car by dt seconds.
37| * input = { throttle: 0..1, brake: 0..1, steer: -1..1 (+ = left), handbrake: bool }
38| */
39|export function stepCar(car, input, spec, dt) {
40|  // Grip-limited steering: never ask the tyres for more than maxLateralAccel (v²/L·tan δ ≤ a).
41|  const steerLimit = Math.min(spec.maxSteer, Math.atan((spec.maxLateralAccel * spec.wheelBase) / (car.speed * car.speed + 1e-6)));
42|  car.steer = approach(car.steer, input.steer * steerLimit, spec.steerRate * dt);
43|
44|  // Throttle accelerates forward (or brakes while rolling backwards), brake does the opposite.
45|  const v = car.speed;
46|  let accel = 0;
47|  if (input.throttle) accel += v < -0.5 ? spec.brakeDecel : input.throttle * spec.engineAccel * (1 - Math.max(v, 0) / spec.maxSpeed);
48|  if (input.brake) accel -= v > 0.5 ? spec.brakeDecel : input.brake * spec.reverseAccel * (1 + Math.min(v, 0) / spec.maxReverse);
49|  car.speed += accel * dt;
50|
51|  // Resistances oppose motion but never reverse it on their own.
52|  let drag = spec.rollingResistance + spec.airDrag * car.speed * car.speed;
53|  if (input.handbrake) drag += spec.handbrakeDecel;
54|  car.speed -= Math.sign(car.speed) * Math.min(Math.abs(car.speed), drag * dt);
55|
56|  // Bicycle model: yaw rate follows from speed, wheel base and steering angle.
57|  const yawRate = (car.speed / spec.wheelBase) * Math.tan(car.steer) * (input.handbrake ? 1.4 : 1);
58|  car.heading += yawRate * dt;
59|  car.x += Math.sin(car.heading) * car.speed * dt;
60|  car.z += Math.cos(car.heading) * car.speed * dt;
61|  car.wheelSpin = (car.wheelSpin + (car.speed / spec.wheelRadius) * dt) % (Math.PI * 2);
62|  return car;
63|}", "total_lines": 63, "file_size": 2853, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// Phase 3: the net client (src/net/client.js), driven END-TO-END through
2|// fakeNet against the real raceState — join, roster, seed, start gate, stage,
3|// turn-away, clean drop, master-clock pings, finish gating, results.
4|import { test } from 'node:test';
5|import assert from 'node:assert/strict';
6|import { FakeNet, FakeServer } from '../server/fakeNet.js';
7|import { createRaceState, CLOSE_FULL } from '../server/raceState.js';
8|import { decode, encode } from '../server/protocol.js';
9|import { createNetClient } from '../src/net/client.js';
10|
11|// A wired server + turnkey net clients on the virtual network. The server
12|// remembers every client message raw (`saw(type)` counts them); each client
13|// records all callbacks in `c.log`.
14|function world({ seed = 42, latency = 0 } = {}) {
15|  const net = new FakeNet();
16|  const server = new FakeServer(net);
17|  const onWire = []; // raw texts exactly as the server received them
18|  const rejects = new Map(); // client conn → { code, reason } the server turned it away with
19|  const race = createRaceState({
20|    seed,
21|    now: () => net.now,
22|    send: (conn, type, data) => conn.send(encode(type, data)),
23|    close: (conn, code, reason) => {
24|      conn.close(code, reason);
25|      // fakeNet's peer side fires onClose() without the code (it is only
26|      // recorded on the closer); the real socket delivers it asynchronously
27|      // with its code. Remember it here and hand it to the client below.
28|      rejects.set(conn.peer, { code, reason });
29|    },
30|    schedule: (delayMs, fn) => net.schedule(delayMs, fn),
31|  });
32|  server.onConnect = (conn) => {
33|    race.connect(conn);
34|    conn.onMessage = (text) => { onWire.push(text); race.onMessage(conn, text); };
35|    conn.onClose = () => race.disconnect(conn);
36|  };
37|  const saw = (type) => onWire.map((t) => { try { return decode(t).type; } catch { return `raw:${t}`; } }).filter((ty) => ty === type);
38|  const client = (name) => {
39|    const conn = server.connect({ latency });
40|    const log = {
41|      roster: [], seedChange: [], stage: [], goAt: [], peerPos: [], peerGone: [],
42|      finishInfo: [], results: [], turnedAway: [], dropped: [],
43|    };
44|    const c = createNetClient({
45|      conn, name, now: () => net.now, every: (ms, fn) => net.schedule(ms, fn),
46|      on: {
47|        roster: (players, s) => log.roster.push({ players, seed: s }),
48|        seedChange: (s) => log.seedChange.push(s),
49|        stage: (s) => log.stage.push(s),
50|        goAt: (g) => log.goAt.push(g),
51|        peerPos: (state) => log.peerPos.push(state),
52|        peerGone: (id) => log.peerGone.push(id),
53|        finishInfo: (f) => log.finishInfo.push(f),
54|        results: (players) => log.results.push(players),
55|        turnedAway: (code, reason) => log.turnedAway.push({ code, reason }),
56|        dropped: (reason) => log.dropped.push(reason),
57|      },
58|    });
59|    c.conn = conn;
60|    c.log = log;
61|    // Replay the turn-away fakeNet fired before any client handler could
62|    // exist (see world.close). The real socket delivers this late, code in hand.
63|    const rej = rejects.get(conn);
64|    if (rej) conn.onClose(rej.code, rej.reason);
65|    return c;
66|  };
67|  return { net, race, client, saw };
68|}
69|
70|test('two clients join → roster + seed → start gate → countdown → racing → relay', () => {
71|  const { net, client } = world();
72|  const a = client('A');
73|  net.advance(0);
74|  assert.equal(a.stage, 'lobby');
75|  assert.deepEqual(a.log.seedChange, [42], 'seedChange fires once for the first roster');
76|  assert.equal(a.canStart, false, 'a lone player cannot start a race');
77|  a.startRace();
78|  assert.equal(a.stage, 'lobby', 'start with 1 player does nothing');
79|
80|  const b = client('B');
81|  net.advance(0);
82|  for (const c of [a, b]) {
83|    assert.deepEqual(c.players.map((p) => p.name).sort(), ['A', 'B']);
84|    assert.equal(c.seed, 42);
85|    assert.equal(c.canStart, true, 'two players open the gate');
86|    assert.deepEqual(c.log.seedChange, [42], 'the same seed never re-fires seedChange');
87|  }
88|  assert.ok(a.log.roster.length === 2, 'roster fired on every roster message for A');
89|  assert.ok(b.log.roster.length === 1, 'roster fired once for late joiner B');
90|
91|  a.startRace();
92|  assert.equal(a.stage, 'countdown');
93|  assert.equal(b.stage, 'countdown', 'stage message reached B');
94|  assert.equal(a.goAt, b.goAt, 'one shared goAt');
95|  assert.equal(new Set(b.log.goAt).size, 1, 'countdown and go carry the same goAt');
96|
97|  net.advance(3000);
98|  assert.equal(a.stage, 'racing');
99|  assert.equal(b.stage, 'racing');
100|
101|  a.sendPos({ x: 1, z: 2, h: 0.5, s: 3 });
102|  net.advance(0);
103|  const relay = b.log.peerPos[0];
104|  assert.ok(relay, 'posRelay flowed through sendPos to the peer');
105|  assert.equal(relay.x, 1);
106|  assert.equal(relay.z, 2);
107|  assert.equal(relay.h, 0.5);
108|  assert.equal(relay.s, 3);
109|  assert.equal(relay.id, a.players.find((p) => p.name === 'A').id, 'relayed under A id');
110|  assert.ok(Number.isFinite(relay.t), 'receive time is attached for the interp buffer');
111|
112|  // sendPos is gated: nobody races from the lobby.
113|  const fresh = world();
114|  const lone = fresh.client('Lone');
115|  fresh.net.advance(0);
116|  lone.sendPos({ x: 1, z: 2, h: 0, s: 0 });
117|  fresh.net.advance(0);
118|  assert.deepEqual(fresh.saw('pos'), [], 'no positions leave the lobby');
119|});
