242|  // Prefab panel slabs ("Plattenbau") on a lawn.
243|  platte(b, rng, cfg, trees) {
244|    b.ground = 'lawn';
245|    const { x0, z0, x1, z1 } = inner(b, cfg);
246|    const alongX = x1 - x0 >= z1 - z0;
247|    const [l0, l1, s0, s1] = alongX ? [x0, x1, z0, z1] : [z0, z1, x0, x1];
248|    const count = s1 - s0 > 55 ? 2 : 1;
249|    const slabs = [];
250|    for (let k = 0; k < count; k++) {
251|      const mid = s0 + ((s1 - s0) * (k + 1)) / (count + 1), m = rng.range(5, 12);
252|      const [a0, a1, c0, c1] = [l0 + m, l1 - m, mid - 6, mid + 6];
253|      const slab = alongX ? { x0: a0, x1: a1, z0: c0, z1: c1 } : { x0: c0, x1: c1, z0: a0, z1: a1 };
254|      slabs.push(slab);
255|      b.buildings.push({
256|        kind: 'platte', ...slab, y0: cfg.curbHeight, height: rng.int(8, 11) * 2.8 + 0.6,
257|        color: rng.pick(PALETTE.platte), roofColor: 0x6f7275, roof: 'flat',
258|      });
259|    }
260|    scatterTrees(trees, rng, { x0, z0, x1, z1 }, 6, cfg, slabs);
261|  },
262|
263|  park(b, rng, cfg, trees) {
264|    b.ground = 'park';
265|    const r = inner(b, cfg);
266|    scatterTrees(trees, rng, r, Math.floor(((r.x1 - r.x0) * (r.z1 - r.z0)) / 220), cfg, []);
267|  },
268|
269|  // Paved square with the TV tower in the middle.
270|  plaza(b, rng, cfg, trees, landmarks) {
271|    b.ground = 'plaza';
272|    const cx = (b.x0 + b.x1) / 2, cz = (b.z0 + b.z1) / 2;
273|    landmarks.push({ kind: 'tvTower', x: cx, z: cz, y: cfg.curbHeight });
274|    const rad = Math.min(b.x1 - b.x0, b.z1 - b.z0) * 0.34;
275|    for (let i = 0; i < 10; i++) {
276|      const a = (i / 10) * Math.PI * 2;
277|      trees.push({ x: cx + Math.cos(a) * rad, y: cfg.curbHeight, z: cz + Math.sin(a) * rad, s: rng.range(0.8, 1) });
278|    }
279|  },
280|};
281|
282|const inner = (b, cfg) => ({ x0: b.x0 + cfg.sidewalk, z0: b.z0 + cfg.sidewalk, x1: b.x1 - cfg.sidewalk, z1: b.z1 - cfg.sidewalk });
283|
284|/** Random trees inside rect r, at least 6 m apart and 3 m away from any `avoid` rect. */
285|function scatterTrees(trees, rng, r, count, cfg, avoid) {
286|  const placed = [];
287|  for (let tries = 0; placed.length < count && tries < count * 15; tries++) {
288|    const x = rng.range(r.x0 + 3, r.x1 - 3), z = rng.range(r.z0 + 3, r.z1 - 3);
289|    if (avoid.some((a) => x > a.x0 - 3 && x < a.x1 + 3 && z > a.z0 - 3 && z < a.z1 + 3)) continue;
290|    if (placed.some((p) => (p.x - x) ** 2 + (p.z - z) ** 2 < 36)) continue;
291|    placed.push({ x, y: cfg.curbHeight, z, s: rng.range(0.8, 1.3) });
292|  }
293|  trees.push(...placed);
