2|// game server's WebSocket, joins with a name, prints everything the server
3|// says, starts the race when two are in the lobby, streams fake positions
4|// while racing and reports a finish. Run two or three of these and watch the
5|// race happen on the REAL socket path that the fakeNet unit tests only mirror.
6|//   node tools/smokeClient.mjs <name> [port]
7|import { encode, decode } from '../server/protocol.js';
8|
9|const name = process.argv[2] ?? 'Smoke';
10|const port = process.argv[3] ?? process.env.PORT ?? '8080';
11|const ws = new WebSocket(`ws://localhost:${port}/ws`);
12|let id = null;
13|
14|ws.onopen = () => {
15|  console.log(`[${name}] connected — joining`);
16|  ws.send(encode('join', { name }));
17|};
18|ws.onerror = (err) => console.log(`[${name}] connection error:`, err?.message ?? err);
19|ws.onmessage = (e) => {
20|  let m;
21|  try { m = decode(e.data); } catch { console.log(`[${name}] ?? ${e.data}`); return; }
22|  console.log(`[${name}] ←`, m.type, m.data);
23|  if (m.type === 'roster') {
24|    id = m.data.players.find((p) => p.name === name)?.id ?? id;
25|    if (m.data.players.length >= 2) ws.send(encode('start', {}));
26|  }
27|  if (m.type === 'go') {
28|    // Fake driving: a taxi-feeling arc down the track, 15 Hz, then a finish.
29|    let x = 0, tick = 0;
30|    const timer = setInterval(() => {
31|      tick++;
32|      x += 1.5;
33|      ws.send(encode('pos', { x, z: 7.5 + Math.sin(tick / 10) * 3, h: Math.PI / 2, s: 15 }));
34|      if (tick === 40) {
35|        clearInterval(timer);
36|        ws.send(encode('finish', { t: Date.now() })); // ms in the shared server clock
37|      }
38|    }, 66);
39|  }
40|};
